UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"月別ページ（WordPress）。日付は 11/01 形式で、年はページ見出し（2026.11）から取る。一覧に start 時刻はなく open のみ（start は詳細ページにあるかもしれないが未確認）。タイトルは補助行 title-top / title / title-bottom を連結。【公演中止】はタイトルに入るので cancelled に写す。カテゴリ（RECOMMEND/FEATURE）は status ではないので使わない。JSON-LD の Event は時刻も出演者名も持たないので使わない。","url_template":"https://www.unit-tokyo.com/schedule/{YYYY}-{MM}/","item":".p-schedule__body > .p-schedule__item","fields":{"date":{"source":{"selector":".p-schedule__item-date"},"pattern":"(?<month>\\d{1,2})/(?<day>\\d{1,2})","year_source":{"source":{"from":"page","selector":".p-schedule__header-title"},"pattern":"(?<year>\\d{4})"}},"title":{"sources":[{"selector":".p-schedule__item-title-top"},{"selector":".p-schedule__item-title"},{"selector":".p-schedule__item-title-bottom"}],"mode":"join"},"artists":{"selector":".p-schedule__item-lineup","split":"\\s*[/／]\\s*","strip":["\\s*※順不同$"]},"times":{"source":{"selector":".p-schedule__item-open"},"patterns":["OPEN\\s*(?<open>\\d{1,2}:\\d{2})"]},"detail_url":{"selector":"a","attr":"href"},"status":[{"value":"cancelled","when":{"text_matches":"【公演中止】"}}]}}' , needs_review = 0 WHERE id = 'src_venue-daikanyama-unit';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"月別の静的ページ。日付は section の直前にある <a name=\"YYMMDD\"> から取る。出演者欄（.artist）は公演名のことも多く、タイトルは .details-title が空なら .artist で補う。時刻は dt が OPEN/START の次の dd から取り、「15:00 / 16:00」は open/start、24:00 のような単独値は start のみ（open なし）。1 日 2 部の「①13:45 / 14:30 ②18:15 / 19:00」は先頭の部だけを取る（2 部目は未対応）。完売表記はページに無く、延期告知はあっても status は割り当てない。","url_template":"https://www.duomusicexchange.com/schedule/{YYYY}/index_{YYYY}-{MM}.html","item":"section#daybox","fields":{"date":{"source":{"from":"prev-sibling","attr":"name"},"pattern":"^(?<yy>\\d{2})(?<month>\\d{2})(?<day>\\d{2})$"},"title":{"sources":[{"selector":".details-title"},{"selector":".artist"}],"mode":"first"},"artists":{"selector":".artist","split":"\\s*[/／\\n]\\s*","strip":["【[^】]*】"]},"times":{"source":{"label":{"selector":"dt","pattern":"^OPEN/START$"}},"patterns":["(?<open>\\d{1,2}:\\d{2})\\s*/\\s*(?<start>\\d{1,2}:\\d{2})","^(?<start>\\d{1,2}:\\d{2})$"]},"price_text":{"label":{"selector":"dt","pattern":"^ADV\\./DOOR$"}},"ticket_url":{"label":{"selector":"dt","pattern":"^Ticket\\.$"},"selector":"a","attr":"href"}}}' , needs_review = 0 WHERE id = 'src_venue-shibuya-duo';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"トップページ（https://www.womb.co.jp/ja）の SSR カードを使う。一覧本体は RSC の JSON にあるが 2.8MB と重く、DOM ルールの範囲外。このため取れるのは直近の約 10 件のみ（フィクスチャでは 10 件）で、月単位の網羅はできない。日付は年なし（11/21 SAT）なので now から推定する。時刻 `23:00-4:30` は先頭を start とし終了は捨てる（WOMB の表記は開始-終了で open は別記されない）。url_template は使わず sources の URL をトップページに向ける必要がある。","item":".events-grid > article.event-card","fields":{"date":{"source":{"selector":".event-date"},"pattern":"(?<month>\\d{1,2})/(?<day>\\d{1,2})"},"title":{"sources":[{"selector":".event-title"}],"mode":"first"},"artists":{"selector":".event-artists","split":"\\s*,\\s*"},"times":{"source":{"selector":".event-time"},"patterns":["^(?<start>\\d{1,2}:\\d{2})\\s*-"]},"detail_url":{"selector":"a","attr":"href"}}}' , needs_review = 0 WHERE id = 'src_venue-shibuya-womb';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"LOFT PROJECT 共通テーマ。日付は time 内の year/month/day を空白区切りで拾う。.soldout は「予約は締めきりました」で完売とは限らないので status には写さない（null のまま）。open が空のカードは時刻 null。出演者末尾の <li>...</li> は省略記号なので除外。","url_template":"https://www.loft-prj.co.jp/schedule/shelter/schedule?scheduleyear={YYYY}&schedulemonth={M}","item":".block_schedule_list .list > .column","fields":{"date":{"source":{"selector":"time"},"pattern":"(?<year>\\d{4})\\s+(?<month>\\d{1,2})\\s+(?<day>\\d{1,2})"},"title":{"sources":[{"selector":".c_title span"}],"mode":"first"},"artists":{"selector":".artist_tag li","exclude":["^(\\.{2,}|…|and more…?)$"]},"times":{"source":{"selector":".open"},"patterns":["OPEN\\s*(?<open>\\d{1,2}:\\d{2})\\s*-\\s*START\\s*(?<start>\\d{1,2}:\\d{2})","START\\s*(?<start>\\d{1,2}:\\d{2})","OPEN\\s*(?<open>\\d{1,2}:\\d{2})"]},"detail_url":{"selector":"a","attr":"href"}}}' , needs_review = 0 WHERE id = 'src_venue-shimokitazawa-shelter';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"LOFT PROJECT 共通テーマ（SHELTER と同じ構造）。メンテナンス等の非公演カードは skip で落とす。24:00 のような深夜開演はそのまま受け入れる。出演者末尾の <li>...</li> と <li>and more…</li> は省略記号なので除外。","url_template":"https://www.loft-prj.co.jp/schedule/loft/schedule?scheduleyear={YYYY}&schedulemonth={M}","item":".block_schedule_list .list > .column","skip":[{"reason":"non-event: maintenance","when":{"in":".c_title","text_matches":"^メンテナンス$"}}],"fields":{"date":{"source":{"selector":"time"},"pattern":"(?<year>\\d{4})\\s+(?<month>\\d{1,2})\\s+(?<day>\\d{1,2})"},"title":{"sources":[{"selector":".c_title span"}],"mode":"first"},"artists":{"selector":".artist_tag li","exclude":["^(\\.{2,}|…|and more…?)$"]},"times":{"source":{"selector":".open"},"patterns":["OPEN\\s*(?<open>\\d{1,2}:\\d{2})\\s*-\\s*START\\s*(?<start>\\d{1,2}:\\d{2})","START\\s*(?<start>\\d{1,2}:\\d{2})","OPEN\\s*(?<open>\\d{1,2}:\\d{2})"]},"detail_url":{"selector":"a","attr":"href"}}}' , needs_review = 0 WHERE id = 'src_venue-shinjuku-loft';
